#!/usr/bin/env bash
# GSZ step123 — fix "removed cart item reappears after refresh". Cart edits now
# replace the server cart (merge never removed). New /api/cart/replace endpoint;
# cart.js uses it on push/remove/clear; cart.js cache-busted to v=3.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step123-$TS"; TMP=$(mktemp -d)
FILES=(routes/cartsync.js public/js/cart.js views/partials/store_bottom.ejs)
echo "==> step123: cart removal fix"
mkdir -p "$BK"; for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/cartsync.js"; node --check "$GSZ/public/js/cart.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/partials/store_bottom.ejs','utf8'),{filename:'$GSZ/views/partials/store_bottom.ejs'});console.log('    store_bottom ok')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
SC=$(curl -s http://127.0.0.1:3900/static/js/cart.js || true); grep -q 'serverReplace' <<<"$SC" && echo "    cart.js v3 serving: OK" || echo "    cart.js check: not found (cache?)"
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step123 OK ✅  Removing a cart item now sticks — it won't reappear after refresh (server cart mirrors your edits)."
